using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

var dll = "/home/runner/.nuget/packages/xunit.v3.extensibility.core/3.2.2/lib/netstandard2.0/xunit.v3.core.dll";
using var stream = File.OpenRead(dll);
using var pe = new PEReader(stream);
var reader = pe.GetMetadataReader();

foreach (var typeDefHandle in reader.TypeDefinitions)
{
    var typeDef = reader.GetTypeDefinition(typeDefHandle);
    var name = reader.GetString(typeDef.Name);
    if (name == "ITestCaseOrderer")
    {
        var ns = reader.GetString(typeDef.Namespace);
        Console.WriteLine($"Found: {ns}.{name}");
        foreach (var methodHandle in typeDef.GetMethods())
        {
            var method = reader.GetMethodDefinition(methodHandle);
            var methodName = reader.GetString(method.Name);
            Console.WriteLine($"  Method: {methodName}");

            var genParams = method.GetGenericParameters();
            foreach (var gpHandle in genParams)
            {
                var gp = reader.GetGenericParameter(gpHandle);
                var gpName = reader.GetString(gp.Name);
                Console.WriteLine($"    GenParam: {gpName}, Attributes: {gp.Attributes}");
                foreach (var constraintHandle in gp.GetConstraints())
                {
                    var constraint = reader.GetGenericParameterConstraint(constraintHandle);
                    var constraintType = constraint.Type;
                    if (constraintType.Kind == HandleKind.TypeReference)
                    {
                        var tr = reader.GetTypeReference((TypeReferenceHandle)constraintType);
                        Console.WriteLine($"      Constraint: {reader.GetString(tr.Namespace)}.{reader.GetString(tr.Name)}");
                    }
                    else if (constraintType.Kind == HandleKind.TypeDefinition)
                    {
                        var td = reader.GetTypeDefinition((TypeDefinitionHandle)constraintType);
                        Console.WriteLine($"      Constraint: {reader.GetString(td.Namespace)}.{reader.GetString(td.Name)}");
                    }
                }
            }
        }
    }
}
